50	std::vector<double> rolling_mean(const std::vector<double>& values, int window) {
51	    if (window <= 0) throw std::invalid_argument("window must be positive");
52	    const std::size_t n = values.size();
53	    std::vector<double> out(n, NaN);
54	    double sum = 0.0;
55	    for (std::size_t i = 0; i < n; ++i) {
